    82|function getCacheControl(filename: string): string {
    83|  if (filename === 'index.html') return 'no-cache, no-store, must-revalidate';
    84|  if (filename === 'ivx-config.json') return 'no-cache, no-store, must-revalidate';
    85|  if (filename === 'robots.txt' || filename === 'sitemap.xml') return 'public, max-age=3600';
    86|  // JS/CSS assets — short cache since they change with deploys
    87|  if (filename.endsWith('.js') || filename.endsWith('.css')) return 'public, max-age=300, s-maxage=600, stale-while-revalidate=1200';
    88|  return 'public, max-age=3600';
